/// These values represent the status of a well or wellbore.
#[derive(Debug, Default, Clone, PartialEq, Eq, Hash, EnergymlEnum)]
#[energyml(
    package = "eml",
    version = "2.2",
    xml_name = "WellStatus"
)]
pub enum WellStatus {
    /// The status of a facility in which drilling,
    /// completion, and production operations have been permanently
    /// terminated.
    #[default]
    #[energyml(value = "abandoned")]
    Abandoned,

    /// For a well to be active, at least one of its
    /// wellbores must be active. For a wellbore to be active, at least
    /// one of its completions must be actively producing or injecting
    /// fluids.
    #[energyml(value = "active")]
    Active,

    /// Fluids are actively being injected into the
    /// facility.
    #[energyml(value = "active -- injecting")]
    ActiveMinusMinusInjecting,

    /// Fluids are actively being produced from the
    /// facility.
    #[energyml(value = "active -- producing")]
    ActiveMinusMinusProducing,

    /// The completion has been installed, but the
    /// facility is not yet active. This status is appropriate only
    /// before the initial producing or injecting activity.
    #[energyml(value = "completed")]
    Completed,

    /// The status of a well or wellbore in which drilling
    /// operations have begun, but are not yet completed. The status ends
    /// when another status becomes appropriate.
    #[energyml(value = "drilling")]
    Drilling,

    /// The wellbore has been plugged from the bottom,
    /// but only partially to the point where it intersects another wellbore.
    #[energyml(value = "partially plugged")]
    PartiallyPlugged,

    /// The facility has received regulatory approvel,
    /// but drilling has not yet commenced. For a well, it has been spudded.
    /// For a subsequent wellbore, the whipstock or similar device has not
    /// yet been set.
    #[energyml(value = "permitted")]
    Permitted,

    /// An abandoned well (or wellbore) whose wellbores
    /// have been plugged in such a manner as to prevent the migration of
    /// oil, gas, salt water, or other substance from one stratum to another.
    /// Generally the criteria for this status is controlled by regulatory
    /// authorities.
    #[energyml(value = "plugged and abandoned")]
    PluggedAndAbandoned,

    /// The status of a well or wellbore from conception
    /// to either regulatory approval or commencement of drilling.
    #[energyml(value = "proposed")]
    Proposed,

    /// The facility has been sold, so it is no longer
    /// appropriate to keep a close internal status value. Status values
    /// may be added at later times without changing the sold status.
    #[energyml(value = "sold")]
    Sold,

    /// Production or injection has been temporarily
    /// suspended in a manner that will allow immediate resumption of
    /// activities.
    #[energyml(value = "suspended")]
    Suspended,

    /// Production or injection has been temporarily
    /// suspended in a manner that will not allow immediate resumption
    /// of activities.
    #[energyml(value = "temporarily abandoned")]
    TemporarilyAbandoned,

    /// The facility operations are suspended while
    /// tests are being conducted to determine formation and/or reservoir
    /// properties. For example, a drillstem test. This status also
    /// includes extended testing.
    #[energyml(value = "testing")]
    Testing,

    /// Information about the status of the well is
    /// confidential. This is more explicit than unknown, since it gives
    /// the reason that the status value is unknown.
    #[energyml(value = "tight")]
    Tight,

    /// Maintenance or data acquisition on a well during
    /// the production phase. This includes any relevant job which can be
    /// done while the well is shut in. This includes many jobs that occur
    /// when a well is re-entered.
    #[energyml(value = "working over")]
    WorkingOver,

    /// The value is not known. This value should not be used
    /// in normal situations. All reasonable attempts should be made to determine
    /// the appropriate value. Use of this value may result in rejection in some situations.
    #[energyml(value = "unknown")]
    Unknown,

}

/// Reference location for the measured depth datum (MdDatum).
/// 
/// The type of local or permanent reference datum for vertical gravity based (i.e., elevation and vertical depth) and measured depth coordinates within the context of a well. This list includes local points (e.g., kelly bushing) used as a datum and vertical reference datums (e.g., mean sea level).
#[derive(Debug, Default, Clone, PartialEq, Eq, Hash, EnergymlEnum)]
#[energyml(
    package = "eml",
    version = "2.2",
    xml_name = "WellboreDatumReference"
)]
pub enum WellboreDatumReference {
    #[default]
    #[energyml(value = "ground level")]
    GroundLevel,

    #[energyml(value = "kelly bushing")]
    KellyBushing,

    /// A tidal datum. The arithmetic mean of hourly heights observed over the National Tidal Datum Epoch (19 years).
    #[energyml(value = "mean sea level")]
    MeanSeaLevel,

    #[energyml(value = "derrick floor")]
    DerrickFloor,

    /// A flange affixed to the top of the casing string used to attach production equipment.
    #[energyml(value = "casing flange")]
    CasingFlange,

    #[energyml(value = "crown valve")]
    CrownValve,

    #[energyml(value = "rotary bushing")]
    RotaryBushing,

    #[energyml(value = "rotary table")]
    RotaryTable,

    #[energyml(value = "sea floor")]
    SeaFloor,

    /// The lowest tide level over the duration of the National Tidal Datum Epoch (19 years).
    #[energyml(value = "lowest astronomical tide")]
    LowestAstronomicalTide,

    /// A tidal datum. The average of the higher high water height of each tidal day observed over the National Tidal Datum Epoch (19 years).
    #[energyml(value = "mean higher high water")]
    MeanHigherHighWater,

    /// A tidal datum. The average of all the high water heights observed over the National Tidal Datum Epoch (19 years).
    #[energyml(value = "mean high water")]
    MeanHighWater,

    /// A tidal datum. The average of the lower low water height of each tidal day observed over the National Tidal Datum Epoch (19 years).
    #[energyml(value = "mean lower low water")]
    MeanLowerLowWater,

    /// A tidal datum. The average of all the low water heights observed over the National Tidal Datum Epoch (19 years).
    #[energyml(value = "mean low water")]
    MeanLowWater,

    /// A tidal datum. The arithmetic mean of mean high water and mean low water. Same as half-tide level.
    #[energyml(value = "mean tide level")]
    MeanTideLevel,

    /// This value is not expected to be used in most typical situations. All reasonable attempts should be made to determine the appropriate value.
    #[energyml(value = "kickoff point")]
    KickoffPoint,

}

